#!/usr/bin/env bash
# Local macOS acceptance script. All samples are generated by the Go program;
# no external files, services, or network endpoints are required.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

OUT="$ROOT/out/acceptance"
rm -rf "$OUT"
mkdir -p "$OUT" bin

echo "== go mod tidy / build / test =="
go mod tidy
go build ./...
go test ./...
go build -o bin/avpipe ./cmd/avpipe

REQUIRED_KEYS=(
  av_sync_ms
  loss_recovery_rate
  p95_latency_ms
  manifest_segments
  alignment_errors
  first_blocked_dependency
  manifest_sha256
)

check_keys() {
  local file="$1"
  for key in "${REQUIRED_KEYS[@]}"; do
    grep -q "^${key}=" "$file" || {
      echo "missing ${key} in $file" >&2
      cat "$file" >&2
      exit 1
    }
  done
}

echo "== damaged/truncated/loss/missing-index sample =="
set +e
./bin/avpipe demo --seed 7 --loss 0.05 --truncate 13 --missing-index \
  --out "$OUT/damaged-a" > "$OUT/damaged-a.txt" 2>&1
damaged_code=$?
set -e
cat "$OUT/damaged-a.txt"
test "$damaged_code" -eq 2
check_keys "$OUT/damaged-a.txt"
grep -q "^first_unreadable_offset=13$" "$OUT/damaged-a.txt"
grep -q "^index_rebuilt=18$" "$OUT/damaged-a.txt"

rate="$(sed -n 's/^loss_recovery_rate=//p' "$OUT/damaged-a.txt")"
awk "BEGIN { exit !($rate >= 0 && $rate <= 1) }"

echo "== deterministic rerun =="
set +e
./bin/avpipe demo --seed 7 --loss 0.05 --truncate 13 --missing-index \
  --out "$OUT/damaged-b" > "$OUT/damaged-b.txt"
rerun_code=$?
set -e
test "$rerun_code" -eq 2
sha_a="$(sed -n 's/^manifest_sha256=//p' "$OUT/damaged-a.txt")"
sha_b="$(sed -n 's/^manifest_sha256=//p' "$OUT/damaged-b.txt")"
test -n "$sha_a"
test "$sha_a" = "$sha_b"
cmp -s "$OUT/damaged-a/manifest.json" "$OUT/damaged-b/manifest.json"

echo "== normal sample =="
set +e
./bin/avpipe demo --seed 7 --out "$OUT/normal" > "$OUT/normal.txt" 2>&1
normal_code=$?
set -e
test "$normal_code" -eq 0
check_keys "$OUT/normal.txt"
sync_ms="$(sed -n 's/^av_sync_ms=//p' "$OUT/normal.txt")"
align_errors="$(sed -n 's/^alignment_errors=//p' "$OUT/normal.txt")"
awk "BEGIN { exit !($sync_ms <= 20) }"
test "$align_errors" -eq 0

echo "== exhausted DAG dependency =="
set +e
./bin/avpipe demo --fail-node align-representations \
  --out "$OUT/blocked" > "$OUT/blocked.txt" 2>&1
blocked_code=$?
set -e
test "$blocked_code" -eq 3
grep -q "^first_blocked_dependency=align-representations$" "$OUT/blocked.txt"

echo "== argument error =="
set +e
./bin/avpipe demo --loss 1.5 > "$OUT/args.txt" 2>&1
args_code=$?
set -e
test "$args_code" -eq 1

echo "== requested go run record =="
# The go command wraps a binary's exit status 2 as go-run exit status 1 while
# printing "exit status 2". The built binary above preserves the contract.
set +e
go run ./cmd/avpipe demo --seed 7 --loss 0.05 --truncate 13 --missing-index
go_run_code=$?
set -e
echo "go_run_wrapped_exit_code=$go_run_code (binary semantic code was 2)"

echo "acceptance passed"
